	import helpers from '../../plugins/helpers.js';

	export default {
		layout: 'home',
		async asyncData({ $content, $axios, params }) {
			const details = await $content(`home/${params.slug}`).fetch();
			const lang = params.slug;

			return {
				$axios,
				details,
				lang,
			}
		},
		data() {
			return {
				sliderList: [],
				bannerList: [],
				announcementlist : [],
				testimonialList: [],
			}
		},
    mounted() {
      helpers.setToken('utm_source', this.$route.query.utm_source);
    },
		created() {
			this.$axios.$get(`/get_home_info/${this.lang}`).then((response) => {
				this.sliderList = response.slider_list;
				this.bannerList = response.banner_list;
				this.announcementlist = response.announcement;
				this.testimonialList = response.testimonial_list;
			});
		},
		head() {
			if(this.details) {
				return {
					title: this.details.pageTitle,
					meta: [
						{
						hid: 'description',
						name: 'description',
						content: this.details.pageDescription
						}
					],
				}
			}
		}
	}
